record.field:
fp = env.company._megga_setup_takeaway_vat()
if fp:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'type': 'success',
            'message': "Position fiscale « %s » prête, reliée au preset "
                       "À l'emporter de la caisse." % fp.name,
            'sticky': False,
        },
    }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'type': 'warning',
            'message': "Le plan comptable suisse manque sur cette "
                       "société : installez d'abord la localisation "
                       "(pays Suisse), puis relancez cette action.",
            'sticky': True,
        },
    }
